diff --git a/mail/components/extensions/child/ext-tabs.js b/mail/components/extensions/child/ext-tabs.js
index cad1e29051d..cb80d815dc2 100644
--- a/mail/components/extensions/child/ext-tabs.js
+++ b/mail/components/extensions/child/ext-tabs.js
@@ -9,12 +9,27 @@ this.tabs = class extends ExtensionAPI {
     return {
       tabs: {
         connect(tabId, options) {
-          const { frameId = null, name = "" } = options || {};
-          return context.messenger.connect({ name, tabId, frameId });
+          const {
+            frameId = null,
+            name = "",
+            documentId = null,
+          } = options || {};
+          return context.messenger.connect({
+            name,
+            tabId,
+            frameId,
+            documentId,
+          });
         },

         sendMessage(tabId, message, options, callback) {
-          const arg = { tabId, frameId: options?.frameId, message, callback };
+          const arg = {
+            tabId,
+            frameId: options?.frameId,
+            documentId: options?.documentId,
+            message,
+            callback,
+          };
           return context.messenger.sendRuntimeMessage(arg);
         },
       },
